OTHER = b"\x08"*32
KA, KB, KC, KD = b"\xaa"*32, b"\xbb"*32, b"\xcc"*32, b"\xdd"*32
KEYS = {"a":KA,"b":KB,"c":KC,"d":KD}
POS = {"a":(3.0,0.0),"b":(0.0,4.0),"c":(0.0,0.0),"d":(50.0,50.0)}
POINT=(0.0,0.0); CTX="room-7"
