def trust(i, root=ROOT, key=None):
    x,y = POS[i]
    return cert(i,x,y,key or KEYS[i],root)
def rec(i, t=0.0, key=None):
    x,y=POS[i]
    return attest_observation_for_point(i,x,y,dec,POINT,CTX,t,key or KEYS[i])

records=[rec("a"),rec("b"),rec("c")]
trusts=[trust("a"),trust("b"),trust("c")]
ev = locate_cert_evidence(records,POINT,CTX,trusts,ROOT)
pol = ConsensusPolicy({"a":1,"b":2,"c":4},5)
wev = locate_weighted_cert_evidence(records,trusts,POINT,CTX,pol,ROOT)

# baseline equivalence
assert audit_cert_evidence_policy(ev, ROOT) == audit_cert_evidence(ev, ROOT)
assert audit_weighted_cert_evidence_policy(wev, ROOT) == audit_weighted_cert_evidence(wev, ROOT)
# bytes form
assert audit_cert_evidence_policy(ev.to_bytes(), ROOT) == audit_cert_evidence(ev, ROOT)

# root TypeError only
try: audit_cert_evidence_policy(ev, bytearray(ROOT))
except TypeError: pass
else: raise AssertionError()
try: audit_cert_evidence_policy(ev, b"")
except ValueError: pass
else: raise AssertionError()
# bad x
try: audit_cert_evidence_policy(42, ROOT)
except ValueError: pass
else: raise AssertionError()

# now required
for kw in (dict(max_age=10.0), dict(trust_revocations=[]), dict(observation_revocations=[]),
           dict(observation_revocation_list=None) ):
    pass
try: audit_cert_evidence_policy(ev, ROOT, max_age=10.0)
except ValueError: pass
else: raise AssertionError("now required")

# now/max_age shape
for bad in (True, "x", float("inf"), float("nan"), None):
    try: audit_cert_evidence_policy(ev, ROOT, now=bad, max_age=10.0)
    except ValueError: pass
    else: raise AssertionError(f"now {bad!r}")
for bad in (True, "x", -1.0, float("inf")):
    try: audit_cert_evidence_policy(ev, ROOT, now=1.0, max_age=bad)
    except ValueError: pass
    else: raise AssertionError(f"max_age {bad!r}")
for bad in (True, 1.0):
    try: audit_cert_evidence_policy(ev, ROOT, now=1.0, max_age=10.0, min=bad)
    except ValueError: pass
    else: raise AssertionError(f"min {bad!r}")

# freshness: issued_at 0, now 0 max_age 0 -> ok boundary
r = audit_cert_evidence_policy(ev, ROOT, now=0.0, max_age=0.0)
assert r.accepted
# stale
try: audit_cert_evidence_policy(ev, ROOT, now=11.0, max_age=10.0)
except ValueError: pass
else: raise AssertionError("stale")
# future
try: audit_cert_evidence_policy(ev, ROOT, now=-1.0, max_age=10.0)
except ValueError: pass
else: raise AssertionError("future")
# without max_age, old obs fine
audit_cert_evidence_policy(ev, ROOT, now=1e9)

# trust revocation (per-call)
tr = revoke_trust(trusts[0], ROOT)
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[tr])
except ValueError as e: pass
else: raise AssertionError("trust rev should reject")
# bytes
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[tr.to_bytes()])
except ValueError: pass
else: raise AssertionError()
# wrong key
tr2 = revoke_trust(trusts[0], OTHER)
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[tr2])
except ValueError: pass
else: raise AssertionError("wrong root rev")
# duplicate pair
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[tr,tr])
except ValueError: pass
else: raise AssertionError("dup")
# unknown cert: forge revocation for different trust mac
t2 = cert("a",3.0,0.0,b"\x01"*32,ROOT)  # same id, different cert/key
trx = revoke_trust(t2, ROOT)
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[trx])
except ValueError: pass
else: raise AssertionError("unknown cert target")
# unknown id
t_other = cert("zz", 1.0,1.0,b"\x02"*32,ROOT)
trz = revoke_trust(t_other, ROOT)
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[trz])
except ValueError: pass
else: raise AssertionError("unknown id")
# malformed bytes
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[b"{}"])
except ValueError: pass
else: raise AssertionError("bad bytes")
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=[42])
except ValueError: pass
else: raise AssertionError("bad item")
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=42)
except ValueError: pass
else: raise AssertionError("non-iterable")

# trust revocation list
crl = make_crl([tr], 1, 0.0, ROOT)
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=crl)
except ValueError: pass
else: raise AssertionError("crl hit reject")
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, trust_revocations=crl.to_bytes())
except ValueError: pass
else: raise AssertionError()
