rv_t = dataclasses.replace(rv, mac=bytes(a^1 for a in rv.mac))
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, observation_revocations=[rv_t])
except ValueError: pass
else: raise AssertionError("tampered obs rev")
# future revocation
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, observation_revocations=[revoke_observation("a",1.0,KA)])
except ValueError: pass
else: raise AssertionError("future obs rev")
# unknown id
try: audit_cert_evidence_policy(ev, ROOT, now=0.0, observation_revocations=[revoke_observation("zz",0.0,b"\x03"*32)])
except ValueError: pass
else: raise AssertionError("unknown obs id")
