import dataclasses
import unittest

from nearproof import (
    Consensus,
    ConsensusPolicy,
    ObservationRevocation,
    ObservationRevocationList,
    RangeDecision,
    TrustRevocation,
    TrustRevocationList,
    VerifierTrust,
    WeightedCertifiedConsensusEvidence,
    WeightedConsensus,
    attest_observation_for_point,
    audit_weighted_cert_evidence,
    audit_weighted_cert_evidence_policy,
    cert,
    locate_weighted_cert_evidence,
    make_crl,
    make_observation_crl,
    revoke_observation,
    revoke_trust,
)

ROOT = b"\x09" * 32
OTHER_ROOT = b"\x08" * 32
KEY_A = b"\xaa" * 32
KEY_B = b"\xbb" * 32
KEY_C = b"\xcc" * 32
KEY_D = b"\xdd" * 32

KEYS = {"a": KEY_A, "b": KEY_B, "c": KEY_C, "d": KEY_D}
POSITIONS = {"a": (3.0, 0.0), "b": (0.0, 4.0), "c": (0.0, 0.0), "d": (50.0, 50.0)}
WEIGHTS = {"a": 1, "b": 2, "c": 4}
THRESHOLD = 5

POINT = (0.0, 0.0)
CONTEXT = "room-7"


def decision(upper_bound=5.0, *, accepted=True, sample_count=1):
    return RangeDecision(
        sample_count=sample_count, upper_bound=upper_bound, accepted=accepted
    )


def policy(weights=None, threshold=THRESHOLD):
    return ConsensusPolicy(WEIGHTS if weights is None else weights, threshold)


def trust(ident, *, root=ROOT, key=None, x=None, y=None):
    px, py = POSITIONS[ident]
    return cert(ident, x if x is not None else px, y if y is not None else py,
                key or KEYS[ident], root)


def record(ident, upper_bound=5.0, *, key=None, point=POINT, context=CONTEXT,
           issued_at=0.0, accepted=True):
    x, y = POSITIONS[ident]
    return attest_observation_for_point(
        ident, x, y, decision(upper_bound, accepted=accepted), point, context,
        issued_at, key or KEYS[ident],
    )


def triangle_records(upper_bound=5.0, **kwargs):
    return [
        record("a", upper_bound, **kwargs),
        record("b", upper_bound, **kwargs),
        record("c", upper_bound, **kwargs),
    ]


def triangle_trusts():
    return [trust("a"), trust("b"), trust("c")]


def make_evidence(records=None, trusts=None, pol=None):
    return locate_weighted_cert_evidence(
        triangle_records() if records is None else records,
        triangle_trusts() if trusts is None else trusts,
        POINT, CONTEXT, policy() if pol is None else pol, ROOT,
    )


class WeightedCertEvidencePolicyDefaultTest(unittest.TestCase):
    def test_matches_existing_audit_item_for_item(self):
        evidence = make_evidence()
        for artifact in (evidence, evidence.to_bytes()):
            self.assertEqual(
                audit_weighted_cert_evidence_policy(artifact, ROOT),
                audit_weighted_cert_evidence(artifact, ROOT),
            )

    def test_returns_weighted_consensus(self):
        evidence = make_evidence()
        result = audit_weighted_cert_evidence_policy(evidence, ROOT)
        self.assertIsInstance(result, WeightedConsensus)
        self.assertEqual(result.total_weight, 7)
        self.assertEqual(result.support_weight, 7)
        self.assertTrue(result.accepted)

    def test_now_and_min_are_ignored_without_a_policy(self):
        evidence = make_evidence()
        audit_weighted_cert_evidence_policy(evidence, ROOT, now="ignored")
        audit_weighted_cert_evidence_policy(evidence, ROOT, min=True)
        audit_weighted_cert_evidence_policy(
            evidence, ROOT, now=None, max_age=None,
            trust_revocations=None, observation_revocations=None,
            observation_revocation_list=None,
        )

    def test_baseline_review_runs_first(self):
        evidence = make_evidence()
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(evidence, OTHER_ROOT)
        tampered = dataclasses.replace(
            evidence, mac=bytes(a ^ 1 for a in evidence.mac)
        )
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(tampered, ROOT, now=0.0)

    def test_root_type_split_is_unchanged(self):
        evidence = make_evidence()
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(evidence, b"")
        for bad in (bytearray(ROOT), "", None, 0):
            with self.assertRaises(TypeError, msg=repr(bad)):
                audit_weighted_cert_evidence_policy(evidence, bad)

    def test_x_must_be_evidence_or_bytes(self):
        for bad in ("x", 123, None, {}, []):
            with self.assertRaises(ValueError, msg=repr(bad)):
                audit_weighted_cert_evidence_policy(bad, ROOT)


class WeightedCertEvidencePolicyClockTest(unittest.TestCase):
    def test_now_required_with_any_policy(self):
        evidence = make_evidence()
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(evidence, ROOT, max_age=1.0)
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(
                evidence, ROOT, trust_revocations=[]
            )
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(
                evidence, ROOT, observation_revocations=[]
            )
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(
                evidence, ROOT,
                observation_revocation_list=self._empty_snapshot(),
            )

    @staticmethod
    def _empty_snapshot():
        return make_observation_crl([], 0, 0.0, ROOT)

    def test_now_contract(self):
        evidence = make_evidence()
        for bad in (True, "1", None, float("inf"), float("nan")):
            with self.assertRaises(ValueError, msg=repr(bad)):
                audit_weighted_cert_evidence_policy(
                    evidence, ROOT, now=bad, max_age=1.0
                )

    def test_max_age_contract(self):
        evidence = make_evidence()
        for bad in (True, "1", -0.1, float("inf"), float("nan")):
            with self.assertRaises(ValueError, msg=repr(bad)):
                audit_weighted_cert_evidence_policy(
                    evidence, ROOT, now=0.0, max_age=bad
                )

    def test_closed_freshness_interval_boundaries(self):
        records = triangle_records()  # all issued_at 0.0
        evidence = make_evidence(records)
        # now == issued_at and max_age == 0 is valid: both boundaries count.
        result = audit_weighted_cert_evidence_policy(
            evidence, ROOT, now=0.0, max_age=0.0
        )
        self.assertEqual(result, audit_weighted_cert_evidence(evidence, ROOT))
        result = audit_weighted_cert_evidence_policy(
            evidence, ROOT, now=5.0, max_age=5.0
        )
        self.assertTrue(result.accepted)

    def test_stale_observation_rejected(self):
        evidence = make_evidence()
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(
                evidence, ROOT, now=5.0001, max_age=5.0
            )

    def test_future_dated_observation_rejected(self):
        records = [
            record("a", issued_at=2.0),
            record("b", issued_at=2.0),
            record("c", issued_at=2.0),
        ]
        evidence = make_evidence(records)
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(
                evidence, ROOT, now=1.0, max_age=10.0
            )

    def test_per_record_age_uses_every_issued_at(self):
        records = [record("a", issued_at=0.0), record("b", issued_at=4.0),
                   record("c", issued_at=2.0)]
        evidence = make_evidence(records)
        with self.assertRaises(ValueError):
            # verifier "a" is stale even though "b"/"c" are fresh.
            audit_weighted_cert_evidence_policy(
                evidence, ROOT, now=5.0, max_age=2.0
            )
        audit_weighted_cert_evidence_policy(
            evidence, ROOT, now=5.0, max_age=5.0
        )


class WeightedCertEvidencePolicyTrustTest(unittest.TestCase):
    def setUp(self):
        self.trusts = triangle_trusts()
        self.evidence = make_evidence(trusts=self.trusts)

    def test_matching_trust_revocation_permanently_rejects(self):
        revocation = revoke_trust(self.trusts[0], ROOT)
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence_policy(
                self.evidence, ROOT, now=1000.0,
                trust_revocations=[revocation],
            )

    def test_accepts_canonical_bytes(self):
        revocation = revoke_trust(self.trusts[0], ROOT)
